mapper.select:
select id, schedule_type, schedule_id, oper_type, schedule_date, mix_area, material_code, before_machine_code,
before_recipe_type,before_recipe_version_id,before_recipe_stage,
before_mid_plan, before_mid_order, before_night_plan, before_night_order, before_day_plan, before_day_order,
after_machine_code, after_recipe_type,after_recipe_version_id,after_recipe_stage, after_mid_plan, after_mid_order,
after_night_plan, after_night_order, after_day_plan,after_day_order, remark, del_flag, create_by, create_time, update_by, update_time,
oper_ip, before_Release_Status, after_Release_Status
from t_schedule_oper_log
where del_flag = '0'
and schedule_type = #{scheduleType}
and schedule_id = #{scheduleId}
and oper_type = #{operType}
and schedule_date = #{scheduleDate}
and mix_area = #{mixArea}
and material_code = #{materialCode}
order by create_time desc
order by ${orderStr}

mapper.insert:
